using System;
using System.IO;
using System.Net;
using System.Net.Http;
using System.Net.Security;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Threading.Tasks;
using System.Collections.Concurrent;

namespace CloudInfra.SDK.Storage
{
    public sealed class CertificatePinningPolicy
    {
        private readonly ConcurrentDictionary<string, string[]> _pinnedHashes;
        private readonly bool _enforceRevocationCheck;
        private readonly int _maxChainDepth;

        public CertificatePinningPolicy(bool enforceRevocation = true, int maxChainDepth = 4)
        {
            _pinnedHashes = new ConcurrentDictionary<string, string[]>(StringComparer.OrdinalIgnoreCase);
            _enforceRevocationCheck = enforceRevocation;
            _maxChainDepth = maxChainDepth;
        }

        public void PinHost(string hostname, params string[] sha256Hashes)
        {
            if (string.IsNullOrWhiteSpace(hostname))
                throw new ArgumentException("Hostname cannot be empty", nameof(hostname));
            if (sha256Hashes == null || sha256Hashes.Length == 0)
                throw new ArgumentException("At least one hash required", nameof(sha256Hashes));
            _pinnedHashes[hostname] = sha256Hashes;
        }

        internal bool HasPinsForHost(string hostname) => _pinnedHashes.ContainsKey(hostname);
        internal string[] GetPins(string hostname) => _pinnedHashes.TryGetValue(hostname, out var pins) ? pins : Array.Empty<string>();
        internal bool EnforceRevocation => _enforceRevocationCheck;
        internal int MaxChainDepth => _maxChainDepth;
    }

    public sealed class SecureUploadClient : IDisposable
    {
        private readonly HttpClient _httpClient;
        private readonly CertificatePinningPolicy _pinPolicy;
        private readonly string _storageEndpoint;
        private bool _disposed;

        public SecureUploadClient(string storageEndpoint, CertificatePinningPolicy pinPolicy)
        {
            _storageEndpoint = storageEndpoint ?? throw new ArgumentNullException(nameof(storageEndpoint));
            _pinPolicy = pinPolicy ?? throw new ArgumentNullException(nameof(pinPolicy));

            var handler = new HttpClientHandler
            {
                ServerCertificateCustomValidationCallback = ValidateServerCertificate,
                CheckCertificateRevocationList = _pinPolicy.EnforceRevocation
            };

            _httpClient = new HttpClient(handler)
            {
                Timeout = TimeSpan.FromSeconds(30)
            };
        }

        private bool ValidateServerCertificate(
            HttpRequestMessage request,
            X509Certificate2 certificate,
            X509Chain chain,
            SslPolicyErrors sslPolicyErrors)
        {
            if (certificate == null || chain == null)
                return false;

            // Phase 1: Check basic SSL policy errors
            if (sslPolicyErrors.HasFlag(SslPolicyErrors.RemoteCertificateNotAvailable))
                return false;

            // Phase 2: Validate chain depth
            if (chain.ChainElements.Count > _pinPolicy.MaxChainDepth)
                return false;

            // Phase 3: Check chain status for critical errors
            var validationResult = ValidateChainStatus(chain, sslPolicyErrors);
            if (!validationResult)
                return false;

            // Phase 4: Certificate pinning verification
            var hostname = request.RequestUri?.Host;
            if (hostname != null && _pinPolicy.HasPinsForHost(hostname))
            {
                return VerifyPinning(certificate, chain, hostname);
            }

            // No pins configured for this host - fall through to default behavior
            return sslPolicyErrors == SslPolicyErrors.None;
        }

        private bool ValidateChainStatus(X509Chain chain, SslPolicyErrors policyErrors)
        {
            // Allow name mismatch only if we're doing our own pinning validation
            var allowableErrors = policyErrors & ~SslPolicyErrors.RemoteCertificateNameMismatch;

            foreach (var status in chain.ChainStatus)
            {
                switch (status.Status)
                {
                    case X509ChainStatusFlags.NoError:
                    case X509ChainStatusFlags.RevocationStatusUnknown:
                    case X509ChainStatusFlags.OfflineRevocation:
                        continue;
                    case X509ChainStatusFlags.UntrustedRoot:
                        // For pinned certificates, we may accept untrusted roots
                        // if the pin matches - this is handled in VerifyPinning
                        continue;
                    default:
                        return false;
                }
            }
            return true;
        }

        private bool VerifyPinning(X509Certificate2 leafCert, X509Chain chain, string hostname)
        {
            var expectedPins = _pinPolicy.GetPins(hostname);
            if (expectedPins.Length == 0)
                return false;

            // Check leaf certificate first
            var leafHash = ComputeCertificateHash(leafCert);
            foreach (var pin in expectedPins)
            {
                if (string.Equals(leafHash, pin, StringComparison.OrdinalIgnoreCase))
                    return true;
            }

            // Check intermediate certificates in chain
            for (int i = 1; i < chain.ChainElements.Count; i++)
            {
                var certHash = ComputeCertificateHash(chain.ChainElements[i].Certificate);
                foreach (var pin in expectedPins)
                {
                    if (string.Equals(certHash, pin, StringComparison.OrdinalIgnoreCase))
                        return true;
                }
            }

            return false;
        }

        private static string ComputeCertificateHash(X509Certificate2 cert)
        {
            using (var sha256 = SHA256.Create())
            {
                // Hash the Subject Public Key Info (SPKI)
                var spki = cert.PublicKey.EncodedKeyValue.RawData;
                var hash = sha256.ComputeHash(spki);
                return Convert.ToBase64String(hash);
            }
        }

        public async Task<UploadResult> UploadBlobAsync(string containerName, string blobName, Stream content)
        {
            ThrowIfDisposed();
            if (string.IsNullOrWhiteSpace(containerName))
                throw new ArgumentException("Container name required", nameof(containerName));
            if (string.IsNullOrWhiteSpace(blobName))
                throw new ArgumentException("Blob name required", nameof(blobName));
            if (content == null)
                throw new ArgumentNullException(nameof(content));

            var requestUri = new Uri($"{_storageEndpoint}/{containerName}/{blobName}");
            using var streamContent = new StreamContent(content);
            streamContent.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/octet-stream");

            var response = await _httpClient.PutAsync(requestUri, streamContent).ConfigureAwait(false);
            response.EnsureSuccessStatusCode();

            return new UploadResult
            {
                StatusCode = (int)response.StatusCode,
                ETag = response.Headers.ETag?.Tag,
                RequestId = response.Headers.GetValues("x-ms-request-id")?.ToString()
            };
        }

        private void ThrowIfDisposed()
        {
            if (_disposed) throw new ObjectDisposedException(nameof(SecureUploadClient));
        }

        public void Dispose()
        {
            if (!_disposed)
            {
                _httpClient?.Dispose();
                _disposed = true;
            }
        }
    }

    public class UploadResult
    {
        public int StatusCode { get; set; }
        public string ETag { get; set; }
        public string RequestId { get; set; }
    }
}
